const { spawnSync } = require("child_process");
const path = require("path");

// Compatibility entry point retained for existing project instructions.
// The aligned Word documents are generated by the Python source below.
// The PowerPoint deck is maintained as the reviewed binary in 01_Slides/.
const script = path.join(__dirname, "generate_aligned_documents.py");
const python = process.env.PYTHON || "python3";
const result = spawnSync(python, [script], { stdio: "inherit" });

if (result.error) {
  console.error(result.error.message);
  process.exit(1);
}

process.exit(result.status ?? 0);
